pub fn register_generated_component_aliases(lua: &Lua) -> mlua::Result<()> {
    let ui: Option<mlua::Table> = lua.globals().get("ui")?;
    let scene: Option<mlua::Table> = lua.globals().get("scene")?;
    if let Some(table) = ui.as_ref() {
        table.set("widget", table.get::<mlua::Function>("find")?)?;
    }
    if let Some(table) = ui.as_ref() {
        table.set("text", table.get::<mlua::Function>("find")?)?;
    }
    if let Some(table) = ui.as_ref() {
        table.set("text_box", table.get::<mlua::Function>("find")?)?;
    }
    if let Some(table) = ui.as_ref() {
        table.set("button", table.get::<mlua::Function>("find")?)?;
    }
    if let Some(table) = scene.as_ref() {
        table.set("node", table.get::<mlua::Function>("find")?)?;
    }
    if let Some(table) = scene.as_ref() {
        table.set("spatial", table.get::<mlua::Function>("find")?)?;
    }
    if let Some(table) = scene.as_ref() {
        table.set("mesh", table.get::<mlua::Function>("find")?)?;
    }
    if let Some(table) = scene.as_ref() {
        table.set("camera", table.get::<mlua::Function>("find")?)?;
    }
    Ok(())
}
